import { userErrorData, userErrorMessage } from "$lib/errors";

/**
 * Report chat parity, Phase C (2026-10-20), W2: the words and rules for
 * Edit, Regenerate and the alternatives switcher. The server keeps one active
 * path per conversation (`convex/lib/chatPath.ts`); the panel shows it.
 */

export type AlternativeKind = "edit" | "regenerate";

export interface TurnAlternatives {
  index: number;
  count: number;
  previousPromptMessageId?: string;
  nextPromptMessageId?: string;
}

/** "Edited by {name}" or "Regenerated by {name}", "you" for your own. */
export function alternativeAuthorLine(
  kind: AlternativeKind | undefined,
  name: string | undefined,
  fromCurrentUser: boolean
): string | null {
  if (!kind) return null;
  const who = fromCurrentUser ? "you" : name;
  if (!who) return null;
  return `${kind === "edit" ? "Edited" : "Regenerated"} by ${who}`;
}

/** The switcher's visible text, "2 / 3". */
export function alternativeCounter(alternatives: TurnAlternatives): string {
  return `${alternatives.index} / ${alternatives.count}`;
}

/** The switcher's accessible name, "Response 2 of 3". */
export function alternativeAccessibleName(alternatives: TurnAlternatives): string {
  return `Response ${alternatives.index} of ${alternatives.count}`;
}

const SWITCH_FAILED_FALLBACK = "That response could not be shown. Try again.";

/** Plain words for a switch the server refused or that never reached it. */
export function alternativeSwitchErrorMessage(error: unknown): string {
  if (userErrorData(error)?.code === "CHAT_TURN_ACTIVE") {
    return "Wait for the reply to finish, then switch responses.";
  }
  return userErrorMessage(error, SWITCH_FAILED_FALLBACK).trim() || SWITCH_FAILED_FALLBACK;
}

/**
 * Edit is offered on a finished writer message on the path, never on an
 * automatic Continue link, and only with a durable turn to rebuild from.
 */
export function canEditTurn(
  turn: { status: string; origin?: string; promptMessageId: string } | undefined
): boolean {
  if (!turn) return false;
  if (turn.origin === "auto_continue") return false;
  return turn.status === "completed" || turn.status === "failed" || turn.status === "aborted";
}
